package com.drivique.api.controller;
import com.drivique.api.dto.*; import com.drivique.api.service.PromotionValidationService; import jakarta.validation.Valid; import java.util.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/v1/promotions") public class PromotionController {private final PromotionValidationService service;public PromotionController(PromotionValidationService service){this.service=service;}@PostMapping("/validate") public PromotionValidationResponseDTO validate(@Valid @RequestBody PromotionValidationRequestDTO input,Authentication authentication){return service.validate(input,authentication.getName());}@GetMapping("/featured") public List<FeaturedPromotionResponseDTO> featured(){return service.featured();}}
